// An event's donation link accepts either a payment URL or a UPI address (virtual payment
// address, e.g. "alumni@okhdfcbank"). UPI addresses can't be opened as links, so the UI shows
// them as copyable text instead of a "Donate Here" button.
const UPI_ADDRESS_PATTERN = /^[a-zA-Z0-9][a-zA-Z0-9._-]{1,255}@[a-zA-Z][a-zA-Z0-9.]{1,63}$/;
const URL_PATTERN = /^(https?|ftp):\/\/\S+$/i;

export const isUpiAddress = (value?: string | null): boolean =>
    !!value && UPI_ADDRESS_PATTERN.test(value.trim());

/** Mirrors the API's UrlOrUpi validation: blank, a URL, or a UPI address. */
export const isValidDonationLink = (value?: string | null): boolean => {
    const trimmed = value?.trim() ?? '';
    return !trimmed || URL_PATTERN.test(trimmed) || UPI_ADDRESS_PATTERN.test(trimmed);
};
